//! Contributor-original page-order fixtures, generated by our writer at test time.
//! https://learn.microsoft.com/en-us/office/vba/api/visio.page.index
use misterdiagram_engine::Session;
use misterdiagram_mcp::{headless::Headless, server::Server};
use misterdiagram_opc::Package;
use serde_json::{Value, json};
use std::{path::Path, process::Command};

fn execute(session: &mut Session, command: &str, params: Value) -> Value {
    session.execute(command, &params).unwrap_or_else(|error| panic!("{command}: {error}"))
}
fn call(server: &mut Server, name: &str, arguments: Value) -> Value {
    let reply = server.handle(json!({"jsonrpc":"2.0","id":1,"method":"tools/call","params":{"name":name,"arguments":arguments}})).unwrap();
    assert_eq!(reply["result"]["isError"], false, "{reply}");
    serde_json::from_str(reply["result"]["content"][0]["text"].as_str().unwrap()).unwrap()
}
fn server(input: &Path) -> Server {
    let mut server = Server::new(Box::new(Headless::new()));
    server.handle(json!({"jsonrpc":"2.0","id":0,"method":"initialize","params":{"protocolVersion":"2025-06-18","capabilities":{},"clientInfo":{"name":"page-order-test","version":"1"}}})).unwrap();
    call(&mut server, "open", json!({"path":input}));
    server
}
fn cli(args: &[&str], input: &Path, output: Option<&Path>) -> Vec<u8> {
    let mut command = Command::new(env!("CARGO_BIN_EXE_misterdiagram"));
    command.args(args).arg(input);
    if let Some(output) = output {
        command.arg(output);
    }
    let result = command.output().unwrap();
    assert!(result.status.success(), "{args:?}: {}", String::from_utf8_lossy(&result.stderr));
    result.stdout
}
fn fixture(input: &Path) {
    let mut s = Session::new();
    execute(&mut s, "page.rename", json!({"name":"Foreground"}));
    for (x, text) in [(1., "First box"), (4., "Second box"), (6., "Third box")] {
        execute(&mut s, "shape.draw.rect", json!({"x":x,"y":6,"width":1.5,"height":1,"text":text,"fill":{"color":"#ffffff","pattern":1}}));
    }
    execute(&mut s, "connector.add", json!({"from":1,"to":2}));
    execute(&mut s, "page.add", json!({"name":"Backdrop"}));
    execute(&mut s, "shape.draw.rect", json!({"x":0,"y":0,"width":8.5,"height":11,"fill":{"color":"#204080","pattern":25},"line":{"pattern":0}}));
    execute(&mut s, "sheet.set", json!({"id":1,"name":"FillBkgnd","value":"#8090a0"}));
    execute(&mut s, "sheet.set", json!({"id":1,"name":"FillGradientEnabled","value":1}));
    execute(&mut s, "sheet.set", json!({"id":1,"name":"FillGradientDir","value":0}));
    for index in 0..10 {
        let suffix = if index == 0 { String::new() } else { format!("[{}]", index + 1) };
        for (cell, value) in [
            ("GradientStopPosition", if index == 0 { "0" } else { "1" }),
            ("GradientStopColor", if index == 0 { "#204080" } else { "#8090a0" }),
            ("GradientStopColorTrans", "0"),
        ] {
            execute(&mut s, "sheet.set", json!({"id":1,"name":format!("FillGradientStops.{cell}{suffix}"),"value":value}));
        }
    }
    execute(&mut s, "page.background", json!({"page":1,"background":2}));
    s.edit_document(|doc, selection| {
        doc.pages.swap(0, 1);
        selection.page = 1;
        Ok(())
    })
    .unwrap();
    execute(&mut s, "file.save", json!({"path":input}));
}
#[test]
fn background_first_exports_foreground_on_every_public_surface() {
    let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../target/debug/page-order-public").join(std::process::id().to_string());
    std::fs::create_dir_all(&dir).unwrap();
    let input = dir.join("background-first.vsdx");
    fixture(&input);
    let doc = misterdiagram_vsdx::read(&input).unwrap();
    assert!(doc.pages[0].is_background());
    assert_eq!(doc.page_index(1), Some(1));
    let mut s = Session::new();
    execute(&mut s, "file.open", json!({"path":input}));
    assert_eq!(s.selection().page, 1);
    let connector = execute(&mut s, "connector.add", json!({"page":1,"from":2,"to":3}))["id"].clone();
    execute(&mut s, "sheet.set", json!({"page":1,"id":connector,"name":"ShapeRouteStyle","value":2}));
    for shared in [false, true] {
        assert_eq!(execute(&mut s, "layout.check", json!({"page":1,"shared_only":shared}))["page"], 1);
    }
    // Reopen the immutable original for export byte comparisons.
    execute(&mut s, "file.open", json!({"path":input,"discard":true}));
    let mut layout = s.clone();
    let background = layout.document().pages[0].clone();
    execute(&mut layout, "layout.tree", json!({"page":1,"root":1,"edges":[[1,2],[1,3]],"fit_page":true,"gutter_x":1,"gutter_y":1}));
    execute(&mut layout, "layout.fan", json!({"page":1,"hub":1,"spokes":[2,3]}));
    assert_eq!(layout.document().pages[0], background);
    assert_eq!(layout.document().pages[1].connects.len(), 4);
    let mut server = server(&input);
    let inspected = call(&mut server, "inspect_document", json!({}));
    assert_eq!(inspected["selection"]["page"], 1);
    assert_eq!(inspected["pages"][0]["name"], "Foreground");
    assert_eq!(inspected["pages"][1]["name"], "Backdrop");
    for ext in ["png", "svg", "pdf", "pptx"] {
        let expected = dir.join(format!("render.{ext}"));
        cli(&["render"], &input, Some(&expected));
        for surface in ["convert", "mcp", "engine", "explicit"] {
            let output = dir.join(format!("{surface}.{ext}"));
            match surface {
                "mcp" => {
                    call(&mut server, "export", json!({"path":output}));
                }
                "engine" => {
                    execute(&mut s, "file.export", json!({"path":output}));
                }
                "explicit" => {
                    cli(&["render", "--page", "1"], &input, Some(&output));
                }
                _ => {
                    cli(&[surface], &input, Some(&output));
                }
            }
            assert_eq!(std::fs::read(&output).unwrap(), std::fs::read(&expected).unwrap(), "{surface}/{ext}");
            if ext == "png" {
                let pixels = image::open(&output).unwrap().to_rgb8();
                // Whole-page background fixes the canvas. The box centre is
                // clear of its text by using a point near the lower edge.
                let x = (1.75 * f64::from(pixels.width()) / 8.5) as u32;
                let y = ((11. - 6.2) * f64::from(pixels.height()) / 11.) as u32;
                assert_eq!(pixels.get_pixel(x, y).0, [255, 255, 255]);
                assert_ne!(pixels.get_pixel(20, 20).0, [255, 255, 255]);
            } else if ext == "svg" {
                let xml = std::fs::read_to_string(&output).unwrap();
                assert!(xml.contains("First box"));
                assert!(xml.contains("<image"));
            } else if ext == "pptx" {
                let package = Package::open(&std::fs::read(&output).unwrap()).unwrap();
                let xml = std::str::from_utf8(package.get("ppt/slides/slide1.xml").unwrap()).unwrap();
                assert!(xml.contains("First box"));
                assert!(xml.contains("gradFill"));
            }
        }
    }
    // A later edit can make a background current, but an omitted export page
    // continues to mean the first foreground page.
    execute(&mut s, "shape.draw.rect", json!({"page":2,"x":0,"y":0,"width":0.1,"height":0.1}));
    let output = dir.join("after-selection.svg");
    execute(&mut s, "file.export", json!({"path":output}));
    assert!(std::fs::read_to_string(output).unwrap().contains("First box"));
    // Retain an optional private witness without committing generated packages.
    if let Some(output) = std::env::var_os("PAGE_ORDER_FIXTURE") {
        std::fs::copy(&input, output).unwrap();
    }
    std::fs::remove_dir_all(dir).unwrap();
}

#[test]
fn interleaved_page_ordinals_cover_inspection_edits_sheet_and_reorder() {
    let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../target/debug/page-order-interleaved").join(std::process::id().to_string());
    std::fs::create_dir_all(&dir).unwrap();
    for first_background in [false, true] {
        let mut s = Session::new();
        execute(&mut s, "page.rename", json!({"name":"ForeOne"}));
        for name in ["BackOne", "ForeTwo", "BackTwo"] {
            execute(&mut s, "page.add", json!({"name":name}));
        }
        s.edit_document(|doc, selection| {
            doc.pages[1].attributes.insert("Background".into(), "1".into());
            doc.pages[3].attributes.insert("Background".into(), "true".into());
            if first_background {
                doc.pages.swap(0, 1);
                doc.pages.swap(2, 3);
            }
            selection.page = doc.page_index(1).unwrap();
            Ok(())
        })
        .unwrap();
        for (ordinal, expected) in ["ForeOne", "ForeTwo", "BackOne", "BackTwo"].into_iter().enumerate() {
            let ordinal = ordinal + 1;
            let index = s.document().page_index(ordinal).unwrap();
            assert_eq!(s.document().pages[index].name, expected);
            assert_eq!(s.document().page_ordinal(index), Some(ordinal));
            execute(&mut s, "shape.draw.rect", json!({"page":ordinal,"x":1,"y":2,"width":1,"height":1,"text":expected,"fill":{"color":"#204080"}}));
            let inspected = execute(&mut s, "shape.inspect", json!({"page":ordinal,"id":1}));
            assert_eq!(inspected["page"], ordinal);
            assert_eq!(execute(&mut s, "document.inspect", json!({}))["selection"]["page"], ordinal);
        }
        let input = dir.join(format!("{first_background}.vsdx"));
        execute(&mut s, "file.save", json!({"path":input}));
        let mut server = server(&input);
        for (ordinal, expected) in [(1, "ForeOne"), (2, "ForeTwo"), (3, "BackOne"), (4, "BackTwo")] {
            let reply = call(&mut server, "inspect_document", json!({"page":ordinal}));
            assert_eq!(reply["pages"].as_array().unwrap().len(), 1);
            assert_eq!(reply["pages"][0]["name"], expected);
            let sheet =
                Command::new(env!("CARGO_BIN_EXE_misterdiagram")).arg("sheet").arg(&input).args(["--page", &ordinal.to_string()]).output().unwrap();
            assert!(sheet.status.success());
            let dump = String::from_utf8(sheet.stdout).unwrap();
            assert!(dump.contains(&format!(":{expected}/ThePage")), "{dump}");
            for other in ["ForeOne", "ForeTwo", "BackOne", "BackTwo"] {
                if other != expected {
                    assert!(!dump.contains(&format!(":{other}/ThePage")));
                }
            }
            let output = dir.join("selected.svg");
            cli(&["render", "--page", &ordinal.to_string()], &input, Some(&output));
            assert!(std::fs::read_to_string(output).unwrap().contains(expected));
        }
        // Omitted multi-page exports include both foregrounds in ordinal order.
        for ext in ["pdf", "pptx"] {
            for surface in ["render", "convert", "mcp"] {
                let output = dir.join(format!("all-{first_background}-{surface}.{ext}"));
                if surface == "mcp" {
                    call(&mut server, "export", json!({"path":output}));
                } else {
                    cli(&[surface], &input, Some(&output));
                }
                let bytes = std::fs::read(output).unwrap();
                if ext == "pdf" {
                    let pdf = hayro_syntax::Pdf::new(bytes).unwrap();
                    assert_eq!(pdf.pages().len(), 2);
                } else {
                    let package = Package::open(&bytes).unwrap();
                    for (index, name) in [(1, "ForeOne"), (2, "ForeTwo")] {
                        let path = format!("ppt/slides/slide{index}.xml");
                        assert!(std::str::from_utf8(package.get(&path).unwrap()).unwrap().contains(name));
                    }
                    assert!(package.get("ppt/slides/slide3.xml").is_none());
                }
            }
        }
        for selected in [1, 2] {
            let mut deletion = s.clone();
            execute(&mut deletion, "shape.draw.rect", json!({"page":selected,"x":1,"y":1,"width":1,"height":1}));
            execute(&mut deletion, "page.delete", json!({"page":1}));
            assert_eq!(deletion.document().pages[deletion.selection().page].name, "ForeTwo");
            assert_eq!(execute(&mut deletion, "document.inspect", json!({}))["selection"]["page"], 1);
        }
        let selected_id = s.document().pages[s.selection().page].id;
        execute(&mut s, "page.reorder", json!({"page":1,"index":2}));
        assert_eq!(s.document().pages[s.selection().page].id, selected_id);
        execute(&mut s, "page.reorder", json!({"page":2,"index":1}));
        assert_eq!(s.document().pages[s.selection().page].id, selected_id);
        for invalid in [json!(0), json!(5), json!(u64::MAX), json!(-1), json!("1")] {
            assert!(s.execute("page.rename", &json!({"page":invalid,"name":"invalid"})).is_err());
        }
        assert_eq!(s.document().page_index(0), None);
        assert_eq!(s.document().page_index(usize::MAX), None);
        assert_eq!(s.document().page_ordinal(usize::MAX), None);
        execute(&mut s, "page.reorder", json!({"page":2,"index":1}));
        assert_eq!(s.document().pages[s.document().page_index(1).unwrap()].name, "ForeTwo");
        assert!(s.execute("page.reorder", &json!({"page":1,"index":3})).is_err());
        execute(&mut s, "page.background", json!({"page":1,"background":4}));
        assert_eq!(s.document().pages[s.document().page_index(1).unwrap()].attributes.get("BackPage").unwrap(), "3");
        assert_eq!(execute(&mut s, "page.add", json!({"name":"New foreground"}))["page"], 3);
        assert_eq!(execute(&mut s, "document.inspect", json!({}))["selection"]["page"], 3);
        execute(&mut s, "page.background", json!({"page":1,"background":2}));
        assert_eq!(execute(&mut s, "document.inspect", json!({}))["selection"]["page"], 2);
        assert_eq!(s.document().pages[s.selection().page].name, "New foreground");
    }
    std::fs::remove_dir_all(dir).unwrap();
}

#[test]
fn no_foreground_defaults_refuse_and_explicit_background_still_exports() {
    let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../target/debug/page-order-empty").join(std::process::id().to_string());
    std::fs::create_dir_all(&dir).unwrap();
    let mut s = Session::new();
    s.edit_document(|doc, _| {
        doc.pages[0].attributes.insert("Background".into(), "1".into());
        Ok(())
    })
    .unwrap();
    for ext in ["png", "svg", "pdf", "pptx"] {
        let output = dir.join(format!("empty.{ext}"));
        assert!(s.execute("file.export", &json!({"path":output})).is_err());
        assert!(!output.exists());
        execute(&mut s, "file.export", json!({"page":1,"path":output}));
        std::fs::remove_file(output).unwrap();
    }
    s.edit_document(|doc, _| {
        doc.pages.clear();
        Ok(())
    })
    .unwrap();
    let result = execute(&mut s, "document.inspect", json!({}));
    assert!(result["pages"].as_array().unwrap().is_empty());
    assert_eq!(result["selection"]["page"], Value::Null);
    assert!(s.execute("file.export", &json!({"path":dir.join("none.svg")})).is_err());
    std::fs::remove_dir_all(dir).unwrap();
}
